validator:
function validate(input) {
  const [{ ProductPurchases = [], ProductInfo = [] }] = input;
  const products = new Set(), spelling = new Map(), bought = new Set();
  for (const [id, category, price] of ProductInfo) {
    if ([id, category, price].includes(null)) return 'No value in ProductInfo may be null.';
    if (products.has(id)) return `product_id ${id} appears twice in ProductInfo.`;
    products.add(id);
    const folded = String(category).toLowerCase();
    if (spelling.has(folded) && spelling.get(folded) !== category) return `Categories ${spelling.get(folded)} and ${category} differ only in letter case.`;
    spelling.set(folded, category);
  }
  for (const [user, product, quantity] of ProductPurchases) {
    if ([user, product, quantity].includes(null)) return 'No value in ProductPurchases may be null.';
    if (!products.has(product)) return `product_id ${product} is not in ProductInfo.`;
    if (!(quantity > 0)) return `quantity ${quantity} must be positive.`;
    const key = `${user}|${product}`;
    if (bought.has(key)) return `(${user}, ${product}) appears twice in ProductPurchases.`;
    bought.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const shuffle = list => { for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; } return list; };
  const names = small ? ['Books', 'Clothing', 'Electronics', 'Sports']
    : ['Books', 'Clothing', 'Electronics', 'Sports', 'Kitchen', 'Garden', 'Toys', 'Music', 'Home Office', 'Beauty'];
  const productCount = small ? 2 + Math.floor(rand() * 5) : 60;
  const ProductInfo = [];
  // Earlier categories get more products, so the pair counts spread out.
  for (let i = 0; i < productCount; i++) ProductInfo.push([small ? 101 + i : 100 + i * 7, names[Math.floor(Math.pow(rand(), 1.6) * names.length)], pick([20, 35, 45, 60, 75, 100, 9.99])]);
  const users = small ? 5 : 300;
  // Most small cases hold 6 to 8 purchases, enough for one category pair to reach three customers.
  const limit = small ? (rand() < 0.15 ? Math.floor(rand() * 6) : 6 + Math.floor(rand() * 3)) : 2000;
  const bought = new Set(), ProductPurchases = [];
  const buy = (user, product) => {
    const key = `${user}|${product}`;
    if (ProductPurchases.length >= limit || bought.has(key)) return;
    bought.add(key);
    ProductPurchases.push([user, product, 1 + Math.floor(rand() * 5)]);
  };
  if (small && rand() < 0.8) {
    // Plant two products of different categories bought by 2 to 4 users, so the pair's count lands just below,
    // on or above the threshold of 3; the remaining purchases often add a second product of the same category.
    const first = pick(ProductInfo), other = ProductInfo.filter(p => p[1] !== first[1]);
    if (other.length) {
      const second = pick(other), sharers = shuffle([1, 2, 3, 4, 5]).slice(0, 2 + Math.floor(rand() * 3));
      for (const user of sharers) { buy(user, first[0]); buy(user, second[0]); }
    }
  }
  for (let tries = 0; ProductPurchases.length < limit && tries < limit * 5; tries++) buy(1 + Math.floor(rand() * users), pick(ProductInfo)[0]);
  return [{ ProductPurchases: shuffle(ProductPurchases), ProductInfo }];
}
